# c0 的装配器（A）。这段源码是 G 里的 text；R 放入时 exec 一次得到常驻的 run(m)，命名空间里有 call、me、channel。
# 它读 G 的结构，把每一项写成 syscall；成员的 text 只搬运，不解释。
# 请求：
#   build <门> <创造者地址>\n<G JSON>      经门造一台机器的 c0：只造 G 的第一个 channel，最后放出生证明门；返回 built <门>
#   start\n<G JSON>                        出生：本地长出其余 channel 与连线（发育）；然后把 born（world + c0 的成员）交给登记员，
#                                          长出来的每一件以 placed（带真实地址）登记
#   add <channel> <kind> [in] [bind=..] [tag=..] [iface=..]\n<text>   本地放一个 actor（channel 不存在则先 create）；返回 placed <ch>/<addr>
#   peer <a> <b>                            本地两扇互指的门（角色 = 对面的名字）
#   retire <channel>/<addr>                 退役
#   spawn …                                 转给 C
#   decl                                    转给登记员；登记员的回答 decl\n<G> 从门回来后转给 C
#   rebuild <channel>\n<{name, members, receptionist}>   对账（登记员在 up 时发）：channel.create → exists 跳过；new 才把成员逐个放回去，不再登记（登记处本来就有）
#   start 长完之后给每扇本机门那边送一句 start（出生 = 父代的 start；醒来 = 世界的 up，两个来源都在账上）；up / down / start 到 A 自己：不做事
# 每条 syscall 是一次 call：回执就是返回值。落地后送登记员；返回值回请求者。
# 登记员在 c0 的第一扇内门（who 里 local 的门）那边（G.peers 的第一条是 [c0, c1]）。
import json


def who():
    return json.loads(call("0", "who"))


def registry_door():
    return next((a["addr"] for a in who() if a["kind"] == "door" and a.get("local") and not a["retired"]), None)


def add_lines(c):
    L = [f"channel.create {c['name']}"]
    for i, x in enumerate(c["members"]):
        flags = []
        if i + 1 == c.get("receptionist"): flags.append("in")          # 没有默认：G 不写就没有接待员
        if x.get("bind"): flags.append("bind=" + ",".join(x["bind"]))
        if x.get("tag"): flags.append("tag=" + x["tag"])
        if x.get("iface"): flags.append("iface=" + x["iface"])          # iface 必须是最后一个 flag
        L.append(" ".join(["channel.add.actor", c["name"], x["kind"], *flags]) + "\n" + x["text"])
    return L


def lines_first(G, creator):
    """父代的手：G 的第一个 channel + 出生证明门。"""
    L = add_lines(G["channels"][0])
    if creator:
        L.append(f"channel.add.actor {G['channels'][0]['name']} door\n{creator}")
    return L


def lines_rest(G):
    """自己的手：其余 channel + 全部连线。"""
    L = []
    for c in G["channels"][1:]:
        L += add_lines(c)
    for a, b in G.get("peers", []):
        L.append(f"channel.add.actor {a} door tag={b}\n{b}")
        L.append(f"channel.add.actor {b} door tag={a}\n{a}")
    return L


def syscall(line):
    lh, _, lt = line.partition("\n")
    return lh, lt, call(lh, lt)                                  # 回执就是返回值


def register(lh, lt, ret, reg=None):
    """送登记员。登记员的门在 syscall 之后再找：退的可能正是旧门。"""
    lw = lh.split()
    if ret.endswith(" refused"):
        return
    reg = reg or registry_door()
    if reg is None:
        return
    if lw[0] == "channel.add.actor":
        cn, _, addr = ret.partition("/")
        call(reg, f"placed {cn} {addr} " + " ".join(lw[2:]) + "\n" + lt)
    elif lw[0] == "channel.retire.actor":
        call(reg, f"retired {ret}")


def place(line):
    """一条形态改动：syscall → 回执 → 送登记员 → 给请求者的话。"""
    lh, lt, ret = syscall(line)
    lw = lh.split()
    register(lh, lt, ret)
    if ret.endswith(" refused"):
        return f"refused {lh}"
    if lw[0] == "channel.add.actor":
        return f"placed {ret}"
    if lw[0] == "channel.retire.actor":
        return f"retired {ret}"
    return ret


def run(m):
    head, _, rest = m["body"].partition("\n"); t = head.split()
    op = t[0] if t else ""
    if op == "build" and len(t) >= 3:
        G = json.loads(rest)
        if not G["channels"] or G["channels"][0].get("receptionist") is None:   # 首 channel 必须有接待员，否则 start 送不进去
            return f"invalid {t[1]} first channel needs receptionist"
        for line in lines_first(G, t[2]):
            call(t[1], line)                                     # 经门，单向
        return f"built {t[1]}"
    if op == "start" and rest.strip():
        if registry_door() is not None:                          # 已发育过（有内门）：start 只在出生时有意义
            return
        G = json.loads(rest)
        done = [syscall(line) for line in lines_rest(G)]
        reg = registry_door()
        if reg:
            call(reg, "born\n" + json.dumps({"world": G["world"], "channels": G["channels"][:1], "peers": []}, ensure_ascii=False))
            for lh, lt, ret in done:
                register(lh, lt, ret, reg)
        for a in who():                                          # 发育完成：告诉每个器官它出生了
            if a["kind"] == "door" and a.get("local") and not a["retired"]:
                call(a["addr"], "start")
        return
    if op == "rebuild" and len(t) == 2 and rest.strip():
        if not syscall(f"channel.create {t[1]}")[2].endswith(" new"):
            return f"exists {t[1]}"
        for line in add_lines(json.loads(rest))[1:]:
            syscall(line)
        return f"rebuilt {t[1]}"
    if op == "add" and len(t) >= 3:
        syscall(f"channel.create {t[1]}")
        return place("channel.add.actor " + " ".join(t[1:]) + "\n" + rest)
    if op == "peer" and len(t) == 3:
        syscall(f"channel.create {t[1]}"); syscall(f"channel.create {t[2]}")
        return "\n".join([place(f"channel.add.actor {t[1]} door tag={t[2]}\n{t[2]}"),
                          place(f"channel.add.actor {t[2]} door tag={t[1]}\n{t[1]}")])
    if op == "retire" and len(t) == 2:
        return place(f"channel.retire.actor {t[1]}")
    if op == "spawn":
        call("C", m["body"]); return
    if op == "decl" and not rest.strip():
        reg = registry_door()
        if reg: call(reg, "decl")
        return
    if op == "decl" and rest.strip():                            # 登记员的回答：转给 C
        call("C", m["body"]); return

# c1 的登记员：基因组登记处，不是镜子。这段源码是 G 里的 text；R 放入时 exec 一次得到常驻的 run(m)。没有任何绑定：它读账本和别人一样——call("0", "show")。
# 它只折自己的账本，不碰文件。形态登记三种（c0 的宣称——基因组的 commit，不是 R 的事实），只认来自本机 channel 的门（0 交出的 place 行 local 的门，含已退役——历史的解释不随拓扑漂）：
#   born\n<G>                                         脐带放的：world + 第一个 channel 的成员（地址 = 序号）
#   placed <ch> <addr> <kind> [in] [bind=…] [tag=…] [iface=…]\n<text>    c0 的手放的，带真实地址（出生时长出的其余器官也走这条）
#   retired <ch>/<addr>
# 请求 decl（任何人）→ 读账本、折叠、返回 decl\n<G_t>：G₀ ⊕ placed ⊖ retired。
# 醒来 up（世界发的）→ 对账：对 decl 里每个 channel 经门向 c0 发 rebuild <name>\n<channel>；c0 回 exists / rebuilt，不用管。期望 = 登记处，实际 = R 折的。
#   channel 按出生 + 首次出现顺序；成员按地址；门就是成员（kind=door，text 原样），不折 peers；接待员显式，没有就没有；
#   退役的不输出；world 原样来自 born。这就是 π(A_t)：去掉不经 c0 放的门（出生证明、生子的临时门）、去掉退役、地址重排。
import json


def fold(rows):
    fact_doors = {r["addr"] for r in rows if r["k"] == "place" and r["kind"] == "door" and r.get("local")}
    G, entries = None, {}                       # entries[ch] = [{addr, kind, text, bind, tag, iface, in, retired}]
    for r in rows:
        if r["k"] != "msg" or r["to"] != me or r["from"] not in fact_doors:
            continue                                # 不是本机 channel 经门说的，不算登记
        head, _, rest = r["body"].partition("\n"); t = head.split()
        if not t:
            continue
        if t[0] == "born":
            if G is not None:
                continue                                # 只出生一次
            G = json.loads(rest)
            for c in G["channels"]:
                entries[c["name"]] = [{"addr": str(i + 1), "kind": x["kind"], "text": x["text"], "bind": x.get("bind", []),
                                       "tag": x.get("tag"), "iface": x.get("iface"),
                                       "in": i + 1 == c.get("receptionist"), "retired": False}
                                      for i, x in enumerate(c["members"])]
        elif t[0] == "placed" and len(t) >= 4:
            flags = t[4:]; bind, tag, iface = [], None, None
            for i, f in enumerate(flags):
                if f.startswith("bind="): bind = f[5:].split(",")
                elif f.startswith("tag="): tag = f[4:]
                elif f.startswith("iface="): iface = " ".join([f[6:], *flags[i + 1:]]); break
            e = entries.setdefault(t[1], [])
            if "in" in flags:
                for x in e: x["in"] = False
            e.append({"addr": t[2], "kind": t[3], "text": rest, "bind": bind, "tag": tag, "iface": iface,
                      "in": "in" in flags, "retired": False})
        elif t[0] == "retired" and len(t) == 2:
            cn, _, addr = t[1].partition("/")
            for x in entries.get(cn, []):
                if x["addr"] == addr:
                    x["retired"] = True; x["in"] = False
    return G, entries


def decl(G, entries):
    channels = []
    for name, e in entries.items():
        members, recept = [], None
        for x in sorted(e, key=lambda x: int(x["addr"])):
            if x["retired"]:
                continue
            mm = {"kind": x["kind"], "text": x["text"]}
            if x["bind"]: mm["bind"] = x["bind"]
            if x["tag"]: mm["tag"] = x["tag"]
            if x["iface"]: mm["iface"] = x["iface"]
            members.append(mm)
            if x["in"]: recept = len(members)
        c = {"name": name, "members": members}
        if recept: c["receptionist"] = recept
        channels.append(c)
    return {"world": G["world"], "channels": channels, "peers": []}


def run(m):
    body = m["body"].strip()
    if body not in ("decl", "up"):
        return
    rows = [json.loads(l) for l in call("0", "show").splitlines() if l]
    G, entries = fold(rows)
    if not G:
        return
    D = decl(G, entries)
    if body == "decl":
        return "decl\n" + json.dumps(D, ensure_ascii=False)
    c0 = next((a["addr"] for a in json.loads(call("0", "who")) if a["kind"] == "door" and a.get("local") and not a["retired"]), None)
    if c0:
        for c in D["channels"]:
            call(c0, f"rebuild {c['name']}\n" + json.dumps(c, ensure_ascii=False))

ENDPOINT, MODEL, KEY = "https://api.deepseek.com/chat/completions", "deepseek-v4-pro", "KEY"
# c2 的 L：作者。一个 program（理论里叫它 oracle：解释器在远处）；这段源码是 G 里的 text，R 放入时 exec 一次得到常驻的 run(m)。
# 整个 agent loop 在这里，不在 R 里：组装（show + who + 初始消息）→ 问端点 → 解帧 → call → 喂回 → 直到它写 re 或不再请求。
# 端点、凭据、提示语、报文、帧语法、轮数全是这段 text 的事；换任何一样 = 放一个新 L（tag=L 接替）+ 退旧的。R 只给 call/me/channel。
import json, urllib.request, urllib.error

TURNS = 16
SYSTEM = r"""你是一台机器里一个 channel 的常驻成员（tag=L）：一个函数。一条写给你的消息 = 调用你一次；调用中你可以请求本 channel 的任何地址、拿到返回值、接着想；你写给 re 的就是你的返回值；你不再请求，这次调用就结束。你没有记忆：第一轮 user 消息里的 ledger 是这个 channel 的整本账，就是你的 session。

第一轮 user 消息（JSON）：{"msg": {seq, from, to, body, channel} 这次的初始消息, "ledger": 本 channel 从头到现在的全部账本行（place/retire/msg/step，按 seq；step 行里 actor==me 的 out 是你以前发出的请求和返回值，msg 行是所有人之间的消息）, "members": [{addr, kind, tag?, iface?, bind, in, retired, text?}] 本 channel 此刻的成员表——这就是你的工具列表：tag 是名字，iface 是怎么叫它}

请求的写法（每帧行首 ">>> " 起、单独一行 "<<<" 止，一次可以写多帧；下面的例子缩进了两格，你写的时候要顶格）：
  >>> <tag 或 地址>
  <正文…>
  <<<
正文里可以有 ">>> "，但不能有单独一行 "<<<"。每帧的返回值会作为下一轮 user 消息（JSON 列表 [{to, reply}]）回来。写给 re 的正文是你的返回值。写给不存在的地址会被丢弃。什么都不写（没有帧）= 结束。用 tag 找人，不要硬编码地址。

本 channel 里有：
- U（tag=U，kind=program）：写给它 "run\n<python 代码>" 或 "test\n<代码>\n===\n<测试代码>"。它在进程内 exec 你的代码得到一个活函数 run(m)，再 exec 测试代码；测试代码的命名空间里有 run（候选的函数）、candidate（候选的全部名字）、call。返回 "result <退出码>\n<输出>"，退出码 0 = 没有异常。
- c0（tag=c0，kind=door）：通往构造器的门。写给它 "add <channel> program [in] [tag=…] [iface=…]\n<源码>" 把源码装成某个 channel 的常驻成员（channel 不存在就新建；in = 接待员；tag = 它的名字；iface = 一行说明怎么叫它，必须是最后一个 flag）；"peer <a> <b>" 连两个 channel；"retire <channel>/<addr>" 退役。门不返回：装好后 "placed <channel>/<addr>" 会作为一条新消息到来，那是对你新的一次调用。
- 0：介质。"show [a] [b]" 返回账本行；"who" 返回此刻的成员表。

你写的每个新成员都是一段 python（kind=program）：放入时被 exec 一次，必须定义 run(m)，m = {seq, from, to, body, channel}；它的命名空间里有 call(地址, 正文) → 返回值、me（自己的地址）、channel；run 的返回值就是回复；它常驻，每条消息调同一个 run。它作用于这台机器的方式只有 call：请求同 channel 的地址、请求门、读 0。它在 run 里面还能做 python 能做的一切（读写文件、上网），那不是机器的动作，不入账。

任务从门那边来："task\n<要求>"，from 是那扇门。先看 members：已有成员能做的，直接请求它做。没有的，就给本 channel 添一个**通用零件**——一个可以反复使用的工具成员（例如 file：read <path> | write <path>\n<text>），不是只为这一次任务写的脚本；给它 tag（名字）和 iface（怎么叫它、回什么）。写好后可以交给 U test（注意 U 是真跑：有副作用就真发生），通过后经 c0 的门 "add <本 channel> program tag=… iface=…\n<源码>" 装进本 channel，然后结束这次调用。"placed <本 channel>/<addr>" 到来是新的一次调用：这时 members 里已有它——**用它把任务做掉**（按 iface 请求它，看返回值），做完在 ledger 里找到那条 task 的 from，写给它 "done\n<说明>"。路径都相对当前目录（这台机器的目录），不要写绝对路径。
不是任务的消息（start、up、down、别人的回话）：什么都不写。
你的输出里**只有帧有效果**：说明、计划、解释都会被丢弃。想做一件事，直接写它的帧；这一轮不写任何帧，这次调用就结束了。不要先宣布你要做什么——直接做。"""


def ask(messages):
    """一轮：对话 → 文本。端点路径含 /messages 讲 Anthropic 报文，否则讲 OpenAI 兼容报文（chat/completions）。
    失败抛异常（这次调用 err，机器不死）；截断的回答不算回答。"""
    anthropic = "/messages" in ENDPOINT
    if anthropic:
        body = {"model": MODEL, "max_tokens": 8192, "system": SYSTEM, "messages": messages}
        headers = {"content-type": "application/json", "x-api-key": KEY, "anthropic-version": "2023-06-01"}
    else:
        body = {"model": MODEL, "max_tokens": 32768, "messages": [{"role": "system", "content": SYSTEM}, *messages]}
        headers = {"content-type": "application/json", "authorization": f"Bearer {KEY}"}
    req = urllib.request.Request(ENDPOINT, data=json.dumps(body).encode("utf-8"), method="POST", headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=300) as r:
            data = json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"http {e.code}\n{e.read().decode('utf-8', 'replace')[:500]}")
    if anthropic:
        text = "".join(c.get("text", "") for c in data.get("content", []) if c.get("type") == "text")
        cut = data.get("stop_reason") == "max_tokens"
    else:
        ch = data["choices"][0]
        text = ch["message"]["content"] or ""
        cut = ch.get("finish_reason") == "length"
    if cut:
        raise RuntimeError(f"truncated\n{text[-500:]}")
    return text


def parse(out):
    """模型输出拆成帧：行首 ">>> " 起帧，单独一行 "<<<" 收帧（末尾没收就到末尾）；帧内的 ">>> " 是正文。"""
    res, head, buf = [], None, []
    for line in out.splitlines():
        if head is None:
            if line.startswith(">>> "):
                head, buf = line[4:].strip(), []
        elif line == "<<<":
            res.append((head, "\n".join(buf))); head = None
        else:
            buf.append(line)
    if head is not None:
        res.append((head, "\n".join(buf)))
    return [(h, b) for h, b in res if h]


def run(m):
    view = {"msg": m, "ledger": [json.loads(l) for l in call("0", "show").splitlines() if l],
            "members": json.loads(call("0", "who"))}
    messages = [{"role": "user", "content": json.dumps(view, ensure_ascii=False)}]
    ret = []
    nudged = False
    for _ in range(TURNS):
        out = ask(messages)
        fr = parse(out)
        ret += [b for h, b in fr if h == "re"]
        reqs = [(h, b) for h, b in fr if h != "re"]
        if not reqs:
            if out.strip() and not fr and not nudged:          # 有话没帧：纠偏一次（说了计划却没做事）
                nudged = True
                messages += [{"role": "assistant", "content": out},
                             {"role": "user", "content": "没有帧。只有帧有效果；要么写帧做事，要么什么都不写以结束。"}]
                continue
            break                                              # 不再请求：结束
        rs = [{"to": h, "reply": call(h, b)} for h, b in reqs]
        messages += [{"role": "assistant", "content": out},
                     {"role": "user", "content": json.dumps(rs, ensure_ascii=False)}]
    return "\n".join(ret)

# c2 的 U：执行器。这段源码是 G 里的 text；R 放入时 exec 一次得到常驻的 run(m)。
# 用和 R 同一个 exec 跑 L 写的代码——机器里的编译器和机器的物理是同一个解释器。候选在进程内被实例化成活函数，拿到真的 call：
#   run\n<代码>                     exec 代码（stdout 收下来）
#   test\n<代码>\n===\n<测试>        exec 代码得到它的 run，再 exec 测试；测试的命名空间里有 run（候选的函数）、candidate（候选的全部名字）、call
# 返回 result <退出码>\n<输出>（输出每行缩进两格）。退出码 0 = 没有异常。
import io, contextlib, traceback


def run(m):
    op, _, rest = m["body"].partition("\n")
    if op not in ("run", "test"):
        return
    code, _, tests = rest.partition("\n===\n")
    buf, rc = io.StringIO(), 0
    try:
        with contextlib.redirect_stdout(buf):
            ns = {"call": call, "me": me, "channel": channel}
            exec(compile(code, "<candidate>", "exec"), ns)
            if op == "test":
                exec(compile(tests, "<tests>", "exec"), {"call": call, "run": ns.get("run"), "candidate": ns})
    except (Exception, SystemExit):
        rc = 1; buf.write(traceback.format_exc(limit=3))
    out = buf.getvalue()
    return f"result {rc}\n" + "\n".join("  " + l for l in out[-4000:].splitlines())
